	/*
     * @param	event CreatePersonEvent
     */
    @EventHandler( payloadType=CreatePersonEvent.class )
    public void handle( CreatePersonEvent event) {
	    LOGGER.info("handling CreatePersonEvent - " + event );
	    Person entity = new Person();
            entity.setPersonId( event.getPersonId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setEmail( event.getEmail() );
            entity.setDepartment( event.getDepartment() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPerson( entity );
    }

    /*
     * @param	event UpdatePersonEvent
     */
    @EventHandler( payloadType=UpdatePersonEvent.class )
    public void handle( UpdatePersonEvent event) {
    	LOGGER.info("handling UpdatePersonEvent - " + event );
    	
	    Person entity = new Person();
            entity.setPersonId( event.getPersonId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setEmail( event.getEmail() );
            entity.setDepartment( event.getDepartment() );
            entity.setRoleAssignments( event.getRoleAssignments() );
            entity.setOwnedPolicies( event.getOwnedPolicies() );
            entity.setCorrectiveActions( event.getCorrectiveActions() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindPerson( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPerson( entity );        
    }
    
