    /**
     * Method to retrieve the Person via an PersonPrimaryKey.
     * @param 	id Long
     * @return 	Person
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Person handle( FindPersonQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPersonId() );
    }
    
    /**
     * Method to retrieve a collection of all Persons
     *
     * @param	query	FindAllPersonQuery 
     * @return 	List<Person> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Person> handle( FindAllPersonQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPerson,
 * but only if the id matches
 *
 * @param		entity	Person
 */
	protected void emitFindPerson( Person entity ) {
		LOGGER.info("handling emitFindPerson" );
		
	    queryUpdateEmitter.emit(FindPersonQuery.class,
	                            query -> query.getFilter().getPersonId().equals(entity.getPersonId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPerson
	 * 
	 * @param		entity	Person
	 */
	protected void emitFindAllPerson( Person entity ) {
		LOGGER.info("handling emitFindAllPerson" );
		
	    queryUpdateEmitter.emit(FindAllPersonQuery.class,
	                            query -> true,
	                            entity);
	}

